const policyResourceExists = `-- name: PolicyResourceExists :one
SELECT CASE $1::text
    WHEN 'tenant' THEN EXISTS (
        SELECT 1 FROM organizations
        WHERE org_id = $2::text AND org_id = $3::text AND is_active = TRUE
    )
    WHEN 'agent' THEN EXISTS (
        SELECT 1 FROM agents WHERE tenant_id = $2::text AND agent_id = $3::text
    )
    WHEN 'queue' THEN EXISTS (
        SELECT 1 FROM queue_properties WHERE tenant_id = $2::text AND queue_id = $3::text
    )
    WHEN 'topic' THEN EXISTS (
        SELECT 1 FROM topic_properties WHERE tenant_id = $2::text AND topic_id = $3::text
    )
    WHEN 'subscription' THEN EXISTS (
        SELECT 1 FROM topic_subscriptions s
        JOIN topic_properties t ON t.topic_id = s.topic_id
        WHERE t.tenant_id = $2::text AND s.subscription_id = $3::text
    )
    ELSE FALSE
END
`

type PolicyResourceExistsParams struct {
	ResourceKind string
	TenantID     string
	ResourceID   string
}

func (q *Queries) PolicyResourceExists(ctx context.Context, arg PolicyResourceExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, policyResourceExists, arg.ResourceKind, arg.TenantID, arg.ResourceID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

